import java.util.*;

class Solution {
    private Map<Integer, List<String>> memo = new HashMap<>();

    public List<String> restoreSpaces(String s, String[] words) {
        Set<String> dict = new HashSet<>(Arrays.asList(words));
        return ways(s, 0, dict);
    }

    private List<String> ways(String s, int start, Set<String> dict) {
        if (memo.containsKey(start)) return memo.get(start);
        List<String> res = new ArrayList<>();
        if (start == s.length()) {
            res.add("");                                   // one empty sentence
        } else {
            for (int end = start + 1; end <= s.length(); end++) {
                String w = s.substring(start, end);
                if (!dict.contains(w)) continue;
                for (String tail : ways(s, end, dict))
                    res.add(tail.isEmpty() ? w : w + " " + tail);
            }
        }
        memo.put(start, res);
        return res;
    }
}

