class Solution:
    def restoreSpaces(self, s: str, words: List[str]) -> List[str]:
        vocab = set(words)
        @lru_cache(maxsize=None)
        def go(i):
            if i == len(s): return [""]
            res = []
            for j in range(i + 1, len(s) + 1):
                w = s[i:j]
                if w in vocab:
                    for rest in go(j): res.append(w + (" " + rest if rest else ""))
            return res
        return go(0)

