function restoreSpaces(s, words) {
  const out = [];
  (function go(i, parts) {
    if (i === s.length) { out.push(parts.join(" ")); return; }
    for (const w of words) if (s.startsWith(w, i)) { parts.push(w); go(i + w.length, parts); parts.pop(); }
  })(0, []);
  return out;
}
